#!/usr/bin/env node
"use strict";

const fs = require("fs");
const path = require("path");

const repoRoot = path.resolve(__dirname, "..");

const GROUPS = [
  {
    bundle: "viewer/app/01-core.js",
    parts: [
      "viewer/app/core/01-runtime-state.js"
    ]
  },
  {
    bundle: "viewer/app/02-descriptions.js",
    parts: [
      "viewer/app/descriptions/01-normalize-and-desc.js"
    ]
  },
  {
    bundle: "viewer/app/03-template-preview.js",
    parts: [
      "viewer/app/template/01-path-resolver.js"
    ]
  },
  {
    bundle: "viewer/app/04-output-render.js",
    parts: [
      "viewer/app/output/01-output-render.js"
    ]
  }
];

function readText(filePath) {
  return fs.readFileSync(filePath, "utf8");
}

function writeText(filePath, text) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, text, "utf8");
}

function normalizeNewlines(text) {
  return String(text || "").replace(/\r\n?/g, "\n");
}

function normalizeSource(text) {
  const normalized = normalizeNewlines(text).replace(/[ \t]+$/gm, "");
  return normalized.trimEnd() ? `${normalized.trimEnd()}\n` : "";
}

function buildBundle(group) {
  const chunks = [];
  for (const partRelPath of group.parts) {
    const absPartPath = path.resolve(repoRoot, partRelPath);
    if (!fs.existsSync(absPartPath)) {
      throw new Error(`Missing runtime source part: ${partRelPath}`);
    }
    const source = normalizeSource(readText(absPartPath));
    if (!source.trim()) {
      throw new Error(`Runtime source part is empty: ${partRelPath}`);
    }
    chunks.push(`// bundled from: ${partRelPath}\n${source}`);
  }

  const bundleText = normalizeSource([
    "/* AUTO-GENERATED by scripts/build-runtime-bundles.js. Do not edit this file directly. */",
    ""
  ].join("\n") + chunks.join("\n"));

  const absBundlePath = path.resolve(repoRoot, group.bundle);
  const current = fs.existsSync(absBundlePath) ? normalizeNewlines(readText(absBundlePath)) : "";
  if (current !== bundleText) {
    writeText(absBundlePath, bundleText);
    return true;
  }
  return false;
}

function main() {
  const rebuiltBundles = [];

  for (const group of GROUPS) {
    if (buildBundle(group)) {
      rebuiltBundles.push(group.bundle);
    }
  }

  if (rebuiltBundles.length) {
    console.log(`Rebuilt ${rebuiltBundles.length} runtime bundles:`);
    for (const relPath of rebuiltBundles) {
      console.log(`  - ${relPath}`);
    }
  } else {
    console.log("Runtime bundles already up to date.");
  }
}

main();
